/**
 * @method
 * @name registerMail
 * @description register Mail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerMail = async function() {
    // alert_parse(dts_Receiver.Text, ",");return;
    if (await scwin.checkForm()) {
        let msg = $c.stf.getMessageParam("MSG-A006", "전송");
        const res = window.confirm(msg);
        if (res) {
            const url = "/EmailMgt.do?method=registerEmail" + "&SCREN_ID=" + "ULDSTF30311.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            // alert(dts_MASTER.Text);
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Master, I:pInputDetail=dts_Receiver, I:pFile=dts_fileData)";
            trs_Save.post();
        }
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    let msg = "";
    if (await scwin.checkFileSize() === false) {
        await $c.win.alert("전체 파일용량은 30MB를 초과할 수 없습니다");
        return false;
    }
    if ($c.ut.email_chk(txb_fromEmail.getValue()) === false) {
        await $c.win.alert("잘못된 이메일 주소입니다.");
        txb_fromEmail.focus();
        return false;
    }
    if (txb_title.getValue() === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "제목");
        await $c.win.alert(msg);
        txb_title.focus();
        return false;
    }
    if (txa_content.getValue() === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "내용");
        await $c.win.alert(msg);
        txa_content.focus();
        return false;
    }
    if (txb_EMP_NO.getValue() === "") {
        await $c.win.alert("세션정보를 받지 못했읍니다.");
        txb_EMP_NO.focus();
        return false;
    }

    // dts_Receiver 에서 CHECK 된 걸 찾는다.
    let total = 0;
    let email_err = "";
    let email_row = "";
    let arrEmail = new Array();
    let arrRow = new Array();
    for (let i = 1; i <= dts_Receiver.getRowCount(); i++) {
        const chk = dts_Receiver.getCellData(i, "CHECK");
        const email = dts_Receiver.getCellData(i, "EMAIL");
        if (chk === "T" || chk === "1") {
            total++;

            // 이메일 체크
            if (!$c.stf.IsValidEmail(email)) {
                email_err += email + "@||@";
                email_row += i + ",";
            }
        }
    }
    arrEmail = email_err.split("@||@");
    arrRow = email_row.split(",");
    if (arrEmail.length > 1) {
        let err_msg = "잘못된 이메일 주소(" + (arrEmail.length - 1) + "건)가 있습니다. 전송하시겠습니까?\n";
        for (let i = 0; i < arrEmail.length; i++) {
            if (i < 10) {
                err_msg += "\n" + arrEmail[i];
            } else {
                err_msg += "\n" + "......";
                i = arrEmail.length;
            }
        }
        dts_Receiver.setRowPosition(arrRow[0], 0);
        grd_Receiver.SetColumn("EMAIL");
        grd_Receiver.focus();
        if (!confirm(err_msg)) {
            return false;
        }
    }
    if (total === 0) {
        await $c.win.alert("선택된 수신자가 없습니다.");
        return false;
    }
    if (js_svrGubun === 'local' || js_svrGubun === 'dev' || js_svrGubun === 'test') {
        await $c.win.alert("◆ 주의 사항 ◆\n\n개발환경에서도 메일이 발송되므로 수신자 메일주소를 확인바랍니다.");
    }
    return true;
};

/**
 * @method
 * @name checkFileSize
 * @description 전체 파일 사이즈 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkFileSize = async function() {
    const maxFileSize = 1024 * 30; // 30MB
    let totalFileSize = 0;
    let isValid = true;
    let aTemp;
    let sTemp;
    for (let i = 1; i <= dts_fileData.getRowCount(); i++) {
        sTemp = dts_fileData.getCellData(i, "FILE_SIZE");
        if (sTemp !== null || sTemp.length < 1) {
            totalFileSize = Number(totalFileSize) + Number(sTemp.replace(/,/g, ""));
        } else {
            await $c.win.alert("파일크기를 찾을 수 없습니다.");
            i = dts_fileData.getRowCount() + 1;
            isValid = false;
        }
    }
    if (totalFileSize > maxFileSize) {
        isValid = false;
    }
    return isValid;
};

/**
 * @method
