/**
 * @method
 * @name setDataFromOpener
 * @description - 2022-07-26 by KHJ
 * @returns {void}
 * @hidden N
 */
scwin.setDataFromOpener = function() {
    if (frame.opener.dts_Target) {
        grd_Receiver.Redraw = false;
        const nRowCnt = frame.opener.dts_Target.getRowCount();

        // for문으로 데이터 넣으면 너무 느림.
        dts_Receiver.setJSON(frame.opener.dts_Target.ExportData(1, nRowCnt, false));
        grd_Receiver.Redraw = true;
    }
};

/**
 * @method
 * @name checkMaxLength
 * @description check Max Length 처리
 * @param {Object} obj 컴포넌트
 * @param {Number} size size
 * @param {String} lbl lbl
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMaxLength = async function(obj, size, lbl) {
    const overLen = ($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        await $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

